package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Sets the sheet's clerk limit and floor, those the form sets. */
public class ApplySettings {
    public void apply(@Val SettingsInput input, @Val Sheet sheet, SheetRepository repository) {
        if (input.setClerkLimit()) {
            sheet.setClerkLimit(input.clerkLimit());
        }
        if (input.setFloor()) {
            sheet.setFloor(input.floor());
        }
        repository.saveAndFlush(sheet);
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records each setting the form set, once it is saved: the clerk limit (blank when there is none), then the floor. */
public class AuditSettingChanged {
    public void audit(@Val SettingsInput input, @Val Sheet sheet,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        SettingsResponse settings = SettingsResponse.from(sheet);
        String head = "SETTING_CHANGED sheet=" + sheet.getId() + " by=" + AuditUser.decode(user);
        if (input.setClerkLimit()) {
            audit.record(head + " key=clerk-limit value=" + (settings.clerkLimit() == null ? "" : settings.clerkLimit()));
        }
        if (input.setFloor()) {
            audit.record(head + " key=floor value=" + settings.floor());
        }
    }
}
package net.officefloor.hq.app.setting;

